            return true;
        }
        return false;
    }
    public void vacate() {
        this.vehicle = null;
        occupied.set(false);
    }
}

public class ParkingFloor {
    private final int floorNumber;
    private final Map<SpotType, Queue<ParkingSpot>> freeSpots = new EnumMap<>(SpotType.class);

    public ParkingFloor(int floorNumber) {
        this.floorNumber = floorNumber;
        for (SpotType t : SpotType.values())
            freeSpots.put(t, new ConcurrentLinkedQueue<>());
    }
    public void addSpot(ParkingSpot spot) { freeSpots.get(spot.getType()).add(spot); }

    // pop candidates until one is atomically claimed
    public ParkingSpot findAndClaim(VehicleType vType, Vehicle v) {
        for (SpotType sType : SpotType.compatible(vType)) {
            Queue<ParkingSpot> queue = freeSpots.get(sType);
            ParkingSpot spot;
            while ((spot = queue.poll()) != null) {
                if (spot.tryOccupy(v)) return spot;   // claimed, done
                // lost the race for this spot; keep trying others
            }
        }
        return null;                                  // floor full for this type
    }
    public void release(ParkingSpot spot) {
        spot.vacate();
        freeSpots.get(spot.getType()).add(spot);      // back on the free list
    }
    public int getFloorNumber() { return floorNumber; }
}

