        freeSpots_[SpotType::SMALL] = {};
        freeSpots_[SpotType::COMPACT] = {};
        freeSpots_[SpotType::LARGE] = {};
    }

    void addSpot(ParkingSpot* spot) { freeSpots_[spot->getType()].push_back(spot); }

    // pop candidates until one is atomically claimed
    ParkingSpot* findAndClaim(VehicleType vType, Vehicle* v) {
        for (SpotType sType : compatible(vType)) {
            auto& queue = freeSpots_[sType];
