        this.entryTime = entryTime;
    }
    public String getId() { return ticketId; }
    public VehicleType getVehicleType() { return vehicleType; }
    public String getSpotId() { return spotId; }
    public Instant getEntryTime() { return entryTime; }
}

public final class Receipt {
    private final String ticketId;
    private final int amountInCents;
    private final Instant exitTime;
    public Receipt(String ticketId, int amountInCents, Instant exitTime) {
        this.ticketId = ticketId; this.amountInCents = amountInCents; this.exitTime = exitTime;
    }
    public int getAmount() { return amountInCents; }
}

public class ParkingLot {
    private final List<ParkingFloor> floors = new CopyOnWriteArrayList<>();
    private final SpotAllocationStrategy allocator;
    private final PricingStrategy pricing;
    private final Map<String, Ticket> activeTickets = new ConcurrentHashMap<>();
    private final Map<String, ParkingSpot> spotIndex = new ConcurrentHashMap<>();
    private final AtomicLong ticketSeq = new AtomicLong(1000);

    public ParkingLot(SpotAllocationStrategy allocator, PricingStrategy pricing) {
        this.allocator = allocator;
        this.pricing = pricing;
    }
    public void addFloor(ParkingFloor floor, List<ParkingSpot> spots) {
        for (ParkingSpot s : spots) { floor.addSpot(s); spotIndex.put(s.getId(), s); }
        floors.add(floor);
    }

    public Ticket parkVehicle(Vehicle v) {
        ParkingSpot spot = allocator.findAndClaim(floors, v);
        if (spot == null) throw new LotFullException(v.getType());
        Ticket t = new Ticket("T-" + ticketSeq.incrementAndGet(), v, spot, Instant.now());
        activeTickets.put(t.getId(), t);
        return t;
    }

    public Receipt unparkVehicle(String ticketId, PaymentStrategy payment) {
        Ticket t = activeTickets.get(ticketId);
        if (t == null) throw new InvalidTicketException(ticketId);
        Instant now = Instant.now();
        int fee = pricing.calculate(t, now);
        if (!payment.pay(fee)) throw new PaymentFailedException(ticketId, fee);
        activeTickets.remove(ticketId);               // close the ticket
        ParkingSpot spot = spotIndex.get(t.getSpotId());
        for (ParkingFloor f : floors)                 // release back to its floor
            if (spotOnFloor(f, spot)) { f.release(spot); break; }
        return new Receipt(ticketId, fee, now);
    }
    private boolean spotOnFloor(ParkingFloor f, ParkingSpot s) {
        return s.getId().startsWith("F" + f.getFloorNumber() + "-");
    }
}

