    ParkingSpot(std::string spotId, SpotType type) : spotId_(std::move(spotId)), type_(type) {}

    const std::string& getId() const { return spotId_; }
    SpotType getType() const { return type_; }

    bool tryOccupy(Vehicle* v) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (occupied_) return false;
        occupied_ = true;
        vehicle_ = v;
        return true;
    }
    void vacate() {
        std::lock_guard<std::mutex> lock(mutex_);
        vehicle_ = nullptr;
        occupied_ = false;
    }

