    std::mutex mutex_;
};

class ParkingFloor {
public:
    explicit ParkingFloor(int floorNumber) : floorNumber_(floorNumber) {
        freeSpots_[SpotType::SMALL] = {};
        freeSpots_[SpotType::COMPACT] = {};
        freeSpots_[SpotType::LARGE] = {};
    }

    void addSpot(ParkingSpot* spot) { freeSpots_[spot->getType()].push_back(spot); }

    ParkingSpot* findAndClaim(VehicleType vType, Vehicle* v) {
        for (SpotType sType : compatible(vType)) {
            auto& queue = freeSpots_[sType];
            while (!queue.empty()) {
                ParkingSpot* spot = queue.front();
                queue.pop_front();
                if (spot->tryOccupy(v)) return spot;
            }
        }
        return nullptr;
    }
    void release(ParkingSpot* spot) {
        spot->vacate();
        freeSpots_[spot->getType()].push_back(spot);
    }
