            return [SpotType.SMALL, SpotType.COMPACT, SpotType.LARGE]
        if v == VehicleType.CAR:
            return [SpotType.COMPACT, SpotType.LARGE]
        if v == VehicleType.TRUCK:
            return [SpotType.LARGE]
        raise ValueError(f"unknown type {v}")


class Vehicle(ABC):
    def __init__(self, plate_number: str, vehicle_type: VehicleType):
        self._plate_number = plate_number
        self._type = vehicle_type

    def get_plate(self) -> str: return self._plate_number
    def get_type(self) -> VehicleType: return self._type


class Bike(Vehicle):
    def __init__(self, plate: str): super().__init__(plate, VehicleType.BIKE)


class Car(Vehicle):
    def __init__(self, plate: str): super().__init__(plate, VehicleType.CAR)


class Truck(Vehicle):
    def __init__(self, plate: str): super().__init__(plate, VehicleType.TRUCK)


class VehicleFactory:
    @staticmethod
    def create(vehicle_type: VehicleType, plate: str) -> Vehicle:
        if vehicle_type == VehicleType.BIKE: return Bike(plate)
        if vehicle_type == VehicleType.CAR: return Car(plate)
        if vehicle_type == VehicleType.TRUCK: return Truck(plate)
        raise ValueError(f"unknown type {vehicle_type}")


class ParkingSpot:
    def __init__(self, spot_id: str, spot_type: SpotType):
        self._spot_id = spot_id
        self._type = spot_type
        self._occupied = False
        self._vehicle: Optional[Vehicle] = None
        self._lock = threading.Lock()

    def get_id(self) -> str: return self._spot_id
    def get_type(self) -> SpotType: return self._type

    def try_occupy(self, vehicle: Vehicle) -> bool:
        with self._lock:
            if self._occupied:
                return False
            self._occupied = True
            self._vehicle = vehicle
            return True

    def vacate(self) -> None:
        with self._lock:
            self._vehicle = None
            self._occupied = False


class ParkingFloor:
    def __init__(self, floor_number: int):
        self._floor_number = floor_number
        self._free_spots: Dict[SpotType, deque] = {t: deque() for t in SpotType}

    def add_spot(self, spot: ParkingSpot) -> None:
        self._free_spots[spot.get_type()].append(spot)

    def find_and_claim(self, vehicle_type: VehicleType, vehicle: Vehicle) -> Optional[ParkingSpot]:
        for spot_type in SpotType.compatible(vehicle_type):
            queue = self._free_spots[spot_type]
            while queue:
                spot = queue.popleft()
                if spot.try_occupy(vehicle):
                    return spot
        return None

    def release(self, spot: ParkingSpot) -> None:
        spot.vacate()
        self._free_spots[spot.get_type()].append(spot)

    def get_floor_number(self) -> int: return self._floor_number


class SpotAllocationStrategy(ABC):
    @abstractmethod
    def find_and_claim(self, floors: List[ParkingFloor], vehicle: Vehicle) -> Optional[ParkingSpot]: ...


class PricingStrategy(ABC):
    @abstractmethod
    def calculate(self, ticket: "Ticket", exit_time: datetime) -> int: ...


class PaymentStrategy(ABC):
    @abstractmethod
    def pay(self, amount_in_cents: int) -> bool: ...


class NearestFirstStrategy(SpotAllocationStrategy):
    def find_and_claim(self, floors: List[ParkingFloor], vehicle: Vehicle) -> Optional[ParkingSpot]:
        for floor in floors:
            spot = floor.find_and_claim(vehicle.get_type(), vehicle)
            if spot is not None:
                return spot
        return None


class HourlyPricing(PricingStrategy):
    _RATE = {VehicleType.BIKE: 100, VehicleType.CAR: 200, VehicleType.TRUCK: 400}

    def calculate(self, ticket: "Ticket", exit_time: datetime) -> int:
        minutes = (exit_time - ticket.get_entry_time()).total_seconds() / 60
        hours = max(1, int((minutes + 59) // 60))
        return hours * HourlyPricing._RATE[ticket.get_vehicle_type()]


class CardGateway:
    @staticmethod
    def charge(token: str, amount_in_cents: int) -> bool:
        return True


class CashPayment(PaymentStrategy):
    def pay(self, amount_in_cents: int) -> bool:
        return True


class CardPayment(PaymentStrategy):
    def __init__(self, card_token: str):
        self._card_token = card_token

    def pay(self, amount_in_cents: int) -> bool:
        return CardGateway.charge(self._card_token, amount_in_cents)


class LotFullException(Exception):
    def __init__(self, vehicle_type: VehicleType):
        super().__init__(f"lot full for {vehicle_type}")


class InvalidTicketException(Exception):
    def __init__(self, ticket_id: str):
        super().__init__(f"invalid ticket {ticket_id}")


class PaymentFailedException(Exception):
    def __init__(self, ticket_id: str, fee: int):
        super().__init__(f"payment failed for {ticket_id} amount {fee}")


class Ticket:
    def __init__(self, ticket_id: str, vehicle: Vehicle, spot: ParkingSpot, entry_time: datetime):
        self._ticket_id = ticket_id
        self._plate_number = vehicle.get_plate()
        self._vehicle_type = vehicle.get_type()
        self._spot_id = spot.get_id()
        self._entry_time = entry_time

    def get_id(self) -> str: return self._ticket_id
    def get_vehicle_type(self) -> VehicleType: return self._vehicle_type
    def get_spot_id(self) -> str: return self._spot_id
    def get_entry_time(self) -> datetime: return self._entry_time


class Receipt:
    def __init__(self, ticket_id: str, amount_in_cents: int, exit_time: datetime):
        self._ticket_id = ticket_id
        self._amount_in_cents = amount_in_cents
        self._exit_time = exit_time

    def get_amount(self) -> int: return self._amount_in_cents


class ParkingLot:
    _ticket_seq = count(1000)

    def __init__(self, allocator: SpotAllocationStrategy, pricing: PricingStrategy):
        self._floors: List[ParkingFloor] = []
        self._allocator = allocator
        self._pricing = pricing
        self._active_tickets: Dict[str, Ticket] = {}
        self._spot_index: Dict[str, ParkingSpot] = {}

    def add_floor(self, floor: ParkingFloor, spots: List[ParkingSpot]) -> None:
        for s in spots:
            floor.add_spot(s)
            self._spot_index[s.get_id()] = s
        self._floors.append(floor)

    def park_vehicle(self, vehicle: Vehicle) -> Ticket:
        spot = self._allocator.find_and_claim(self._floors, vehicle)
        if spot is None:
            raise LotFullException(vehicle.get_type())
        ticket = Ticket(f"T-{next(ParkingLot._ticket_seq)}", vehicle, spot, datetime.now())
        self._active_tickets[ticket.get_id()] = ticket
        return ticket

    def unpark_vehicle(self, ticket_id: str, payment: PaymentStrategy) -> Receipt:
        ticket = self._active_tickets.get(ticket_id)
        if ticket is None:
            raise InvalidTicketException(ticket_id)
        now = datetime.now()
        fee = self._pricing.calculate(ticket, now)
        if not payment.pay(fee):
            raise PaymentFailedException(ticket_id, fee)
        del self._active_tickets[ticket_id]
        spot = self._spot_index[ticket.get_spot_id()]
        for floor in self._floors:
            if self._spot_on_floor(floor, spot):
                floor.release(spot)
                break
        return Receipt(ticket_id, fee, now)

    @staticmethod
    def _spot_on_floor(floor: ParkingFloor, spot: ParkingSpot) -> bool:
        return spot.get_id().startswith(f"F{floor.get_floor_number()}-")


if __name__ == "__main__":
    lot = ParkingLot(NearestFirstStrategy(), HourlyPricing())

    f1 = ParkingFloor(1)
    lot.add_floor(f1, [
        ParkingSpot("F1-S1", SpotType.SMALL),
        ParkingSpot("F1-C1", SpotType.COMPACT),
