    car = VehicleFactory.create(VehicleType.CAR, "KA-01-1234")
    ticket = lot.park_vehicle(car)
    print(f"Parked at {ticket.get_spot_id()}")

    receipt = lot.unpark_vehicle(ticket.get_id(), CashPayment())
    print(f"Paid {receipt.get_amount()} cents")
